// Fretwell Music Lab — service worker (generated by scripts/build.mjs).
// Precaches the practice room and every tool so they work offline once loaded.
// Pages are fetched from the network first and fall back to the cache when offline.
const CACHE = 'fretwell-858fc4c2c32f';
const FONT_CACHE = 'fretwell-fonts';
const FONTS_CSS = 'https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,500..900&family=IBM+Plex+Mono:wght@500;600&family=Instrument+Sans:wght@400..700&display=swap';
const PRECACHE = [
  "practice/",
  "practice/manifest.webmanifest",
  "unlock/",
  "favicon.svg",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/apple-touch-icon.png",
  "css/app.css",
  "css/site.css",
  "js/app/app.js",
  "js/app/registry.js",
  "js/app/staff-editor.js",
  "js/app/store.js",
  "js/app/toolkit.js",
  "js/core/art.js",
  "js/core/audio.js",
  "js/core/chord-anim.js",
  "js/core/fretwork.js",
  "js/core/harmony-sets.js",
  "js/core/instruments.js",
  "js/core/jazz.js",
  "js/core/key-input.js",
  "js/core/keys.js",
  "js/core/license.js",
  "js/core/melody.js",
  "js/core/notation.js",
  "js/core/rhythm.js",
  "js/core/sound-ui.js",
  "js/core/synth.js",
  "js/core/theory.js",
  "js/core/voicelead.js",
  "js/pages/demos.js",
  "js/pages/home.js",
  "js/pages/product.js",
  "js/pages/thank-you.js",
  "js/pages/unlock.js",
  "js/products.js",
  "js/site-config.js",
  "js/site.js",
  "js/tools/atelier.js",
  "js/tools/chord-builder.js",
  "js/tools/interval-trainer.js",
  "js/tools/jazz-harmony.js",
  "js/tools/melodic-dictation.js",
  "js/tools/note-reader.js",
  "js/tools/progression-lab.js",
  "js/tools/rhythm-lab.js",
  "js/tools/scale-explorer.js"
];

// Fonts are cached on a best-effort basis so text keeps its typeface offline; failures never block installation.
async function cacheFonts() {
  try {
    const c = await caches.open(FONT_CACHE);
    if (await c.match(FONTS_CSS)) return;
    const res = await fetch(FONTS_CSS, { mode: 'cors' });
    if (!res.ok) return;
    await c.put(FONTS_CSS, res.clone());
    const css = await res.text();
    const urls = [...css.matchAll(/url\((https:[^)]+)\)/g)].map((m) => m[1]);
    await Promise.all(urls.map((u) => fetch(u, { mode: 'cors' }).then((r) => (r.ok ? c.put(u, r) : null)).catch(() => null)));
  } catch { /* offline or blocked: system fonts are used instead */ }
}

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE.map((p) => new URL(p, self.registration.scope).href))).then(() => cacheFonts()).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('fretwell-') && k !== CACHE && k !== FONT_CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(caches.open(FONT_CACHE).then(async (c) => {
      const hit = await c.match(req);
      if (hit) return hit;
      try { const res = await fetch(req); if (res.ok || res.type === 'opaque') c.put(req, res.clone()); return res; } catch { return hit || Response.error(); }
    }));
    return;
  }
  if (url.origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    event.respondWith(fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }).catch(async () => (await caches.match(req, { ignoreSearch: true })) || (await caches.match(new URL('practice/', self.registration.scope).href)) || Response.error()));
    return;
  }
  event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => {
    const network = fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }).catch(() => hit);
    return hit || network;
  }));
});
